/* Prisma Studio — carrega o motor ONNX local em partes pequenas.
 * Carregamento sob demanda, quatro arquivos por vez, sem CDN ou fetch(file://).
 * ONNX Runtime Web 1.20.1: licença MIT em licencas/onnxruntime-web-MIT.txt.
 */
(function(){const base=new URL('.',document.currentScript.src).href;
 let promise;window.PrismaORTLoad=()=>promise||=(async()=>{
  const count=53;window.PrismaORTChunks=[];let next=0;
  await Promise.all(Array.from({length:4},async()=>{while(next<count){const n=next++;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=base+'chunks/part-'+String(n).padStart(3,'0')+'.js';script.onload=resolve;script.onerror=()=>reject(Error('Parte do motor local ausente. Extraia o ZIP completo.'));document.head.append(script);});}}));
  const wasm=window.PrismaORTChunks.join('');delete window.PrismaORTChunks;
  return {wasm,mjs:""};
 })();})();
